        "exceeds_expectations": [
          "Designs and implements robust, scalable solutions with minimal defects.",
          "Introduces patterns or tools that raise overall code quality.",
          "Consistently anticipates edge cases and performance implications."
        ],
        "meets_expectations": [
          "Delivers well-structured, maintainable code following team standards.",
          "Writes adequate tests and resolves defects promptly.",
          "Effectively debugs and refactors when needed."
        ],
        "needs_improvement": [
          "Produces code with recurring defects or maintainability issues.",
          "Tests are incomplete or missing; relies on others to find issues.",
          "Struggles with debugging or solving technical problems independently."
        ]
      },
      "evidence_prompts": [
        "Link to PRs demonstrating complexity handled.",
        "Examples of performance improvements or refactors.",
        "Test coverage or reliability metrics."
      ]
    },
    {
      "id": "SYSTEM_DESIGN",
      "name": "System Design & Architecture",
      "weight": 0.14,
      "behaviors": {
        "exceeds_expectations": [
          "Designs systems/components with clear SLAs, scalability, and reliability.",
          "Balances trade-offs and aligns designs with long-term architecture.",
          "Mentors others on design principles and reviews architecture documents."
        ],
        "meets_expectations": [
          "Creates sound designs for features with appropriate trade-offs.",
          "Documents decisions and aligns with architecture guidelines.",
          "Participates constructively in design reviews."
        ],
        "needs_improvement": [
          "Designs lack clarity on trade-offs or non-functional requirements.",
          "Relies heavily on guidance for common design problems.",
          "Documentation is incomplete or missing."
        ]
      },
      "evidence_prompts": [
        "Design docs and review outcomes.",
        "Incident or performance data post-launch.",
        "Diagrams and decision logs."
