          "Contributes to knowledge sharing."
        ],
        "needs_improvement": [
          "Slow to adapt to new tools or feedback.",
          "Limited participation in learning or knowledge sharing.",
          "Resists change without rationale."
        ]
      },
      "evidence_prompts": [
        "Courses, certifications, or internal talks.",
        "Examples of process/tooling improvements.",
        "Feedback received and applied."
      ]
    },
    {
      "id": "LEADERSHIP_INFLUENCE",
      "name": "Leadership & Influence (appropriate to level)",
      "weight": 0.12,
      "behaviors": {
        "exceeds_expectations": [
          "Leads initiatives across teams; aligns stakeholders and drives outcomes.",
          "Mentors peers; raises the bar for engineering practices.",
          "Influences strategy with data and clear reasoning."
        ],
        "meets_expectations": [
          "Leads within scope; coordinates small projects effectively.",
          "Provides mentorship or onboarding support.",
          "Constructively challenges decisions with evidence."
        ],
        "needs_improvement": [
          "Avoids ownership or leadership opportunities.",
          "Limited influence on team direction or practices.",
          "Feedback or challenges lack clarity or evidence."
        ]
      },
      "evidence_prompts": [
        "Projects led and their outcomes.",
        "Mentorship/coaching examples.",
        "Influence on roadmaps or technical strategy."
      ]
    }
  ],
  "rating_calculation": {
    "method": "Weighted average of competency ratings (1-5) using provided weights.",
    "note": "Adjust weights by role level if needed (e.g., higher weight on design/leadership for senior+)."
  },
  "role_level_adjustments": [
    {
      "level": "Junior/Entry (L1-L2)",
      "emphasis": "Technical execution, growth, and collaboration.",
      "weight_overrides": { "TECHNICAL_EXECUTION": 0.22, "LEARNING_GROWTH": 0.12, "LEADERSHIP_INFLUENCE": 0.06 }
