    },
    {
      "level": "Senior (L4-L5)",
      "emphasis": "System design, impact, leadership.",
      "weight_overrides": { "SYSTEM_DESIGN": 0.18, "LEADERSHIP_INFLUENCE": 0.16, "LEARNING_GROWTH": 0.06 }
