    {
      "level": "Staff+ (L6+)",
      "emphasis": "Org-wide influence, strategy, and reliability.",
      "weight_overrides": { "LEADERSHIP_INFLUENCE": 0.2, "IMPACT": 0.16, "DELIVERY_EXECUTION": 0.16 }
    }
  ],
  "review_sections": [
    {
      "id": "SUMMARY",
      "title": "Overall Summary",
      "instructions": "Summarize key achievements, strengths, and growth areas. Reference evidence and impact."
    },
    {
      "id": "GOALS",
      "title": "Goals & Outcomes",
      "instructions": "List goals set for the period, outcomes achieved, and supporting metrics.",
      "fields": [
        { "name": "goal", "type": "string" },
