/* GOOD: Avoid executing shell commands; use safe Java APIs instead.
   If you truly must run a process, avoid the shell and avoid concatenation.
   Here we read a file using Java NIO with strict validation and whitelisting. */
import javax.servlet.http.*;
import java.io.*;
import java.nio.file.*;
import java.util.Set;

public class SafeFileServlet extends HttpServlet {

    private static final Path BASE_DIR = Paths.get("/var/app/data").toAbsolutePath().normalize();
    private static final Set<String> WHITELIST = Set.of("report.txt", "summary.log");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String filename = req.getParameter("file");
        if (filename == null || !WHITELIST.contains(filename)) {
            resp.sendError(400, "Invalid file requested");
            return;
        }

        Path requested = BASE_DIR.resolve(filename).normalize();
        if (!requested.startsWith(BASE_DIR) || !Files.isRegularFile(requested)) {
            resp.sendError(403, "Access denied");
            return;
        }

        // Safely read the file without invoking a shell
        resp.setContentType("text/plain; charset=UTF-8");
        try (BufferedReader br = Files.newBufferedReader(requested);
             PrintWriter out = resp.getWriter()) {
            String line;
            while ((line = br.readLine()) != null) {
                out.println(line);
            }
        }
    }
}

